import React, { useEffect, useState } from 'react';
import { Card, Row, Col, Badge } from 'react-bootstrap';
import { Line, Bar } from 'react-chartjs-2';
import { io } from 'socket.io-client';
import api from '../services/api';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  BarElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

const Analytics = () => {
  const [salesList, setSalesList] = useState([]);
  const [liveFeed, setLiveFeed] = useState([]);

  useEffect(() => {
    api.get('/sales')
      .then((res) => setSalesList(res.data || []))
      .catch((err) => console.error('Error fetching sales analytics:', err));

    const socket = io('http://localhost:5000');

    socket.on('saleAdded', (payload) => {
      setSalesList((prev) => [...prev, payload]);
      setLiveFeed((prev) => [payload, ...prev.slice(0, 7)]);
    });

    return () => {
      socket.disconnect();
    };
  }, []);

  const totalRevenue = salesList.reduce((acc, curr) => acc + (Number(curr.amount) || 0), 0);
  const avgSale = salesList.length ? totalRevenue / salesList.length : 0;

  const chartLabels = salesList.map((s, idx) =>
    s.createdAt
      ? new Date(s.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      : `Sale #${idx + 1}`
  );
  const chartAmounts = salesList.map((s) => Number(s.amount) || 0);

  const lineChartData = {
    labels: chartLabels.length ? chartLabels : ['No Data'],
    datasets: [
      {
        label: 'Real-Time Revenue ($)',
        data: chartAmounts.length ? chartAmounts : [0],
        borderColor: '#4318ff',
        backgroundColor: (context) => {
          const ctx = context.chart.ctx;
          const gradient = ctx.createLinearGradient(0, 0, 0, 300);
          gradient.addColorStop(0, 'rgba(67, 24, 255, 0.35)');
          gradient.addColorStop(1, 'rgba(67, 24, 255, 0.0)');
          return gradient;
        },
        tension: 0.4,
        fill: true,
        pointBackgroundColor: '#4318ff',
        pointRadius: 4,
        pointHoverRadius: 7,
      },
    ],
  };

  const barChartData = {
    labels: chartLabels.slice(-8),
    datasets: [
      {
        label: 'Recent Transaction Amounts ($)',
        data: chartAmounts.slice(-8),
        backgroundColor: '#05cd99',
        borderRadius: 8,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: false },
      tooltip: {
        backgroundColor: '#1b2559',
        titleFont: { family: 'Plus Jakarta Sans', size: 13, weight: 'bold' },
        bodyFont: { family: 'Plus Jakarta Sans', size: 12 },
        padding: 12,
        cornerRadius: 10,
      },
    },
    scales: {
      x: { grid: { display: false } },
      y: { grid: { color: 'rgba(0, 0, 0, 0.05)' }, beginAtZero: true },
    },
  };

  return (
    <div>
      <div className="d-flex justify-content-between align-items-center mb-4">
        <div>
          <h3 className="fw-bold mb-1">Real-Time Analytics</h3>
          <p className="text-muted small mb-0">Live transaction metrics powered by WebSockets</p>
        </div>
        <div className="d-flex align-items-center gap-2 bg-body p-2 px-3 rounded-pill shadow-sm">
          <span className="live-pulse"></span>
          <span className="small fw-semibold">Live WebSocket Active</span>
        </div>
      </div>

      {/* Metric Cards */}
      <Row className="g-3 mb-4">
        <Col lg={4} md={6}>
          <div className="stat-card shadow-sm">
            <div className="stat-icon primary">💰</div>
            <div>
              <div className="text-muted small fw-semibold text-uppercase">Total Revenue</div>
              <h3 className="fw-extrabold mb-0">${totalRevenue.toLocaleString(undefined, { minimumFractionDigits: 2 })}</h3>
            </div>
          </div>
        </Col>

        <Col lg={4} md={6}>
          <div className="stat-card shadow-sm">
            <div className="stat-icon success">📈</div>
            <div>
              <div className="text-muted small fw-semibold text-uppercase">Total Sales Count</div>
              <h3 className="fw-extrabold mb-0">{salesList.length} Entries</h3>
            </div>
          </div>
        </Col>

        <Col lg={4} md={12}>
          <div className="stat-card shadow-sm">
            <div className="stat-icon warning">⚡</div>
            <div>
              <div className="text-muted small fw-semibold text-uppercase">Avg Sale Value</div>
              <h3 className="fw-extrabold mb-0">${avgSale.toFixed(2)}</h3>
            </div>
          </div>
        </Col>
      </Row>

      {/* Charts */}
      <Row className="g-4 mb-4">
        <Col lg={8}>
          <Card className="p-4 border-0">
            <h5 className="fw-bold mb-3">Live Revenue Trend</h5>
            <div style={{ height: '320px' }}>
              <Line data={lineChartData} options={chartOptions} />
            </div>
          </Card>
        </Col>

        <Col lg={4}>
          <Card className="p-4 border-0">
            <h5 className="fw-bold mb-3">Recent Volume</h5>
            <div style={{ height: '320px' }}>
              <Bar data={barChartData} options={chartOptions} />
            </div>
          </Card>
        </Col>
      </Row>

      {/* Live Feed */}
      <Card className="p-4 border-0">
        <div className="d-flex justify-content-between align-items-center mb-3">
          <h5 className="fw-bold mb-0">Live Socket Transaction Feed</h5>
          <Badge bg="success" className="px-3 py-2 rounded-pill">Real-Time Sync</Badge>
        </div>
        {liveFeed.length === 0 ? (
          <p className="text-muted small mb-0">Waiting for live transactions from staff panel...</p>
        ) : (
          <div className="d-flex flex-column gap-2">
            {liveFeed.map((evt, idx) => (
              <div 
                key={idx} 
                className="d-flex justify-content-between align-items-center p-3 rounded-3"
                style={{ background: 'var(--bg-primary)' }}
              >
                <div className="d-flex align-items-center gap-3">
                  <div className="stat-icon success" style={{ width: '40px', height: '40px', fontSize: '18px' }}>
                    +
                  </div>
                  <div>
                    <div className="fw-semibold">Sale Added</div>
                    <div className="text-muted small">{new Date(evt.createdAt || Date.now()).toLocaleTimeString()}</div>
                  </div>
                </div>
                <div className="fw-bold text-success fs-5">+${Number(evt.amount).toFixed(2)}</div>
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  );
};

export default Analytics;
